  ('0b538a2e-b498-fe69-9244-c1fe271277bc', '8361667e-d96e-eef7-06b1-a83b5a26fef8', 'RECEIPT', 'WIT-R-2026-085-01', 1, '2026-10-08', null, 'issued', 'Liquor Store Management System — Multi-Branch Edition', 'Received with thanks from Mr. Jayantha Munaweera the sum stated below, as the first part of the 40% advance payment towards the Year 1 project fees.', array[]::uuid[], '[]'::jsonb, '{"payment_description":"Advance payment (part 1 of the 40% advance) — Liquor Store Management System, Multi-Branch Edition","payment_detail":"Towards the Year 1 project fees for the main branch and 10 outlets, as per Quotation WIT-Q-2026-085-R1","software_label":"project advance","hardware_label":"POS hardware + manager tablet","against_invoice_id":"6a3a926f-41c4-48e3-80e8-0912e7480ac6","against_invoice_no":"WIT-INV-2026-085-03"}'::jsonb, array[]::uuid[], array[]::uuid[], 300000),
  ('6cb2530c-0f20-8712-7b1c-607076be685d', '8361667e-d96e-eef7-06b1-a83b5a26fef8', 'RECEIPT', 'WIT-R-2026-085-02', 2, '2026-10-27', null, 'issued', null, null, array[]::uuid[], '[]'::jsonb, '{"software_label":"project advance","hardware_label":"POS hardware + manager tablet","invoice_detail":"Advance Rs. 760,000.00 + POS hardware Rs. 419,300.00 + manager tablet Rs. 87,000.00","against_invoice_id":"6a3a926f-41c4-48e3-80e8-0912e7480ac6","against_invoice_no":"WIT-INV-2026-085-03"}'::jsonb, array[]::uuid[], array[]::uuid[], 500000),
  ('7b0ea7ff-abd1-0187-0b26-61fa567e7830', '8361667e-d96e-eef7-06b1-a83b5a26fef8', 'RECEIPT', 'WIT-R-2026-085-03', 3, '2026-10-27', null, 'issued', 'Liquor Store Management System — Advance & Hardware', 'Received with thanks from Mr. Jayantha Munaweera the sum stated below, as the final payment of Invoice WIT-INV-2026-085-03 (project advance and hardware).', array[]::uuid[], '[]'::jsonb, '{"payment_description":"Final payment — Invoice WIT-INV-2026-085-03","payment_detail":"Balance for the POS hardware and manager tablet supplied to Thambapanni Wine Stores, Godagama","invoice_detail":"Advance Rs. 760,000.00 + POS hardware Rs. 419,300.00 + manager tablet Rs. 87,000.00","software_label":"project advance","hardware_label":"POS hardware + manager tablet","thanks_title":"Thank you — Invoice WIT-INV-2026-085-03 will be fully settled once the cheque clears.","thanks_body":"The 40% project advance, the POS hardware and the manager tablet for Thambapanni Wine Stores, Godagama will be fully settled when this cheque is realised. We will confirm with you once the payment has cleared. We truly appreciate your prompt payments.","footnote_extra":"Invoice WIT-INV-2026-085-04 (hardware sets for City Light, Thalathuoya and Royal Wine Stores, Rs. 690,300.00) is billed separately and is not covered by this receipt. The remaining 60% of the project fees is invoiced as each outlet goes live, as per the Project Agreement.","against_invoice_id":"6a3a926f-41c4-48e3-80e8-0912e7480ac6","against_invoice_no":"WIT-INV-2026-085-03"}'::jsonb, array[]::uuid[], array[]::uuid[], 466300);
